struct Countdown: Sequence, IteratorProtocol {
    var n: Int
    mutating func next() -> Int? {     // serves both protocols
        defer { n -= 1 }
        return n > 0 ? n : nil          // nil ends the traversal
    }
}
for i in Countdown(n: 3) { print(i) }   // 3 2 1

